const irQ = (it: IrQ, ask: T3): Draw[] => [A.wipe(), head(ask, 70, 32), qt(`(${it[0]})`, 400, 160, 28, "k"), ...svLines(it[1], 250, 40, "b", 30)];

defineUnit({id: "sv8g", year: 8, ord: 7, title: t3("Krönikan om skärmtid", "The column about screen time", "مقالة عن وقت الشاشة"), storyTitle: "Krönikan om skärmtid",
  icon: ICON(`<rect x="40" y="26" width="120" height="130" fill="#fff" stroke="#9aa8c4" stroke-width="3"/><rect x="52" y="40" width="96" height="14" fill="#1d2433"/>${[0, 1, 2, 3, 4, 5].map(i => `<rect x="52" y="${66 + i * 13}" width="${i % 3 === 2 ? 60 : 96}" height="6" fill="#c9d2e3"/>`).join("")}<g transform="translate(230 92) rotate(12)"><rect x="-34" y="-58" width="68" height="116" rx="12" fill="#33415c"/><rect x="-26" y="-46" width="52" height="86" rx="5" fill="#9fd0f5"/><text y="6" font-size="34" text-anchor="middle">😵</text></g>`, "#fdf3e3"),
  words: ["kronika", "skarmtid", "beroende", "ironi", "overdriva", "reflektera", "vana", "flod8"],
  story: [
    {text: ["Det var en grå tisdag i oktober. Lena delade ut skoltidningen Björkbladet i 8B. ”Den här veckan har vi en krönika av Sara”, sa hon. ”Den handlar om skärmtid. En krönika är en personlig text där skribenten tycker till, ofta med humor.”", "Amir bläddrade fram till sidan fem. Där stod rubriken: ”Hjälp, min mobil har tagit över mitt liv!” Bredvid fanns en bild på Sara med en mobil i varje hand."],
      pic: P7[0], say: t3("En krönika är en personlig text i en tidning. Vad handlar Saras krönika om?", "A column is a personal text in a newspaper. What is Sara's column about?", "المقالة نصّ شخصيّ في صحيفة. عمّ تتحدّث مقالة سارة؟")},
    {text: ["”I söndags bestämde jag mig för att räkna min skärmtid”, skrev Sara. ”Det var ett misstag. Enligt mobilen hade jag tittat på skärmen i nio timmar. Nio! På den tiden hade jag kunnat läsa en hel bok, baka tre tårtor och lära mig japanska.", "Det började oskyldigt. Jag skulle bara kolla en sak i mitt flöde. En stund senare hade jag sett fyrtio videor om katter som är rädda för gurkor.”"],
      pic: P7[1], say: t3("Sara räknar sin skärmtid. Hur många timmar blev det?", "Sara counts her screen time. How many hours was it?", "سارة تحسب وقت الشاشة. كم ساعة كان؟")},
    {text: ["”Mina tummar har sprungit ett maraton i år”, fortsatte krönikan. ”Om man räknar alla meter som jag har scrollat, har jag säkert nått månen och kommit tillbaka.", "Ibland undrar jag om jag är beroende. Nej då, inte alls. Jag kan sluta när jag vill. Jag vill bara aldrig.” Amir skrattade högt. Det var precis så det kändes för honom också."],
      pic: P7[2], say: t3("Har Saras tummar sprungit ett maraton på riktigt? Nej, hon överdriver.", "Have Sara's thumbs really run a marathon? No, she is exaggerating.", "هل ركضت إبهاما سارة ماراثونًا حقًّا؟ لا، إنها تبالغ.")},
    {text: ["”Hemma har vi förstås en regel: inga mobiler vid middagen”, skrev Sara. ”Det är en fantastisk regel. Nu sitter vi tysta och väntar på att middagen ska ta slut, så att vi äntligen kan gå till våra rum och chatta med varandra. Vilken härlig gemenskap!”", "Ibrahim räckte upp handen. ”Hon menar väl inte att det är härligt på riktigt?” ”Nej”, sa Lena. ”Det kallas ironi. Man säger motsatsen till det man menar.”"],
      pic: P7[3], say: t3("Sara skriver att regeln är fantastisk. Menar hon det? Lena förklarar ordet ironi.", "Sara writes that the rule is fantastic. Does she mean it? Lena explains the word irony.", "تكتب سارة أن القاعدة رائعة. هل تقصد ذلك؟ لينا تشرح كلمة السخرية.")},
    {text: ["Men i slutet bytte Sara ton. ”Skämt åsido”, skrev hon. ”Jag tror inte att mobilen är farlig. Men jag har fått en vana som jag inte har valt själv. Så fort jag har tråkigt i en sekund, tar handen fram mobilen. Jag har slutat reflektera, slutat dagdrömma och slutat titta ut genom bussfönstret.", "Därför tar jag ansvar nu. Jag tänker inte kasta mobilen i sjön. Men jag och mobilen ska göra en kompromiss: ibland får den ligga i ett annat rum.”"],
      pic: P7[4], say: t3("Nu skämtar Sara inte längre. Vilken vana vill hon ändra?", "Now Sara isn't joking any more. Which habit does she want to change?", "الآن لم تعد سارة تمزح. ما العادة التي تريد أن تغيّرها؟")},
    {text: ["”Överdriver hon inte lite?” frågade Noah. ”Är nio timmar ens en rimlig siffra?” ”Klart att hon överdriver”, sa Elsa. ”Det är ju det som gör texten rolig. Men poängen är sann.”", "Lena nickade. ”I en krönika får man överdriva för att få läsaren att tänka. Det viktiga är att vi hör skribentens röst. Man ska känna att det är Sara som skriver och inte vem som helst.”"],
      pic: P7[5], say: t3("Klassen pratar om krönikan. Varför får man överdriva i en krönika, enligt Lena?", "The class talks about the column. Why are you allowed to exaggerate in a column, according to Lena?", "يتحدّث الصف عن المقالة. لماذا يجوز أن تبالغ في المقالة، حسب لينا؟")},
    {text: ["På kvällen kollade Amir sin egen skärmtid: sju timmar och tolv minuter. Han stängde av mobilen och lade den i köket. Det kändes konstigt, nästan som en frånvaro av något viktigt.", "Yasmin tittade på honom. ”Är du sjuk?” ”Nej”, sa Amir. ”Jag reflekterar.” ”Vad betyder det?” ”Att jag tänker. Prova du också.” Yasmin funderade en sekund. Sedan tog hon fram sin surfplatta."],
      pic: P7[6], say: t3("Amir lägger bort mobilen. Varför tror Yasmin att han är sjuk?", "Amir puts his phone away. Why does Yasmin think he is ill?", "يضع أمير هاتفه جانبًا. لماذا تظنّ ياسمين أنه مريض؟")}],
  wordsSay: t3("Nya ord från krönikan! Tryck på ett ord för att se vad det betyder.", "New words from the column! Tap a word to see what it means.", "كلمات جديدة من المقالة! اضغط على كلمة لترى معناها."),
  grammar: [
    {draw: () => [A.wipe(), head(t3("Ironi: säga motsatsen", "Irony: saying the opposite", "السخرية: قول العكس")), qt(L(t3("(Det ösregnar.)", "(It is pouring with rain.)", "(المطر غزير.)")), 400, 120, 26, "k"),
      ...boxes([["”Vilket", null], ["underbart", "o", L(t3("säger", "says", "يقول"))], ["väder!”", null]], 210, 42),
      A.arrow(400, 252, 400, 296, "k"),
      ...boxes([["Vilket", null], ["hemskt", "r", L(t3("menar", "means", "يقصد"))], ["väder.", null]], 350, 42),
      qt(L(t3("Ironi = man säger motsatsen till det man menar.", "Irony = you say the opposite of what you mean.", "السخرية = أن تقول عكس ما تقصد.")), 400, 460, 26, "b")],
    say: t3("När det ösregnar och någon säger ”Vilket underbart väder!”, menar hen motsatsen: vädret är hemskt. Det är ironi. Man förstår ironin genom situationen och tonen.", "When it is pouring and someone says ”What wonderful weather!”, they mean the opposite: the weather is awful. That is irony. You understand irony from the situation and the tone.", "عندما يكون المطر غزيرًا ويقول أحدهم «يا له من طقس رائع!» فهو يقصد العكس: الطقس سيّئ. هذه سخرية. نفهم السخرية من الموقف ومن نبرة الصوت.")},
    {draw: () => [A.wipe(), head(t3("Överdrift: göra det större", "Exaggeration: making it bigger", "المبالغة: تكبير الأمر")),
      ...boxes([["Mina tummar har sprungit", null], ["ett maraton.", "o", L(t3("överdrift", "exaggeration", "مبالغة"))]], 180, 38),
      A.arrow(400, 222, 400, 270, "k"),
      ...boxes([["Jag har scrollat", null], ["väldigt mycket.", "g", L(t3("menar", "means", "يقصد"))]], 320, 38),
      qt(L(t3("Ingen tror att det är sant – och det är meningen!", "Nobody believes it is true – and that is the point!", "لا أحد يصدّق أنه حقيقيّ، وهذا هو المقصود!")), 400, 440, 26, "b")],
    say: t3("Sara skriver att hennes tummar har sprungit ett maraton. Det är en överdrift. Hon menar bara att hon scrollar väldigt mycket. Överdriften gör texten rolig och lätt att minnas.", "Sara writes that her thumbs have run a marathon. That is an exaggeration. She just means that she scrolls a lot. The exaggeration makes the text funny and easy to remember.", "تكتب سارة أن إبهاميها ركضا ماراثونًا. هذه مبالغة. هي تقصد فقط أنها تتصفّح كثيرًا جدًّا. المبالغة تجعل النص مضحكًا وسهل التذكّر.")},
    {draw: () => {
      const L1 = [t3("neutral, inget jag", "neutral, no I", "محايد، بلا «أنا»"), t3("bara fakta", "only facts", "حقائق فقط"), t3("allvarlig ton", "serious tone", "نبرة جادّة")];
      const L2 = [t3("jag + min åsikt", "I + my opinion", "أنا + رأيي"), t3("humor, ironi, överdrift", "humour, irony, exaggeration", "دعابة وسخرية ومبالغة"), t3("en poäng i slutet", "a point at the end", "فكرة مهمّة في النهاية")];
      return [A.wipe(), head(t3("Skribentens röst", "The writer's voice", "صوت الكاتب")), A.tx(L(t3("Nyhetsartikel", "News article", "خبر صحفي")), 210, 130, 34, "k"), A.tx(L(t3("Krönika", "Column", "مقالة رأي")), 590, 130, 36, "o"),
        A.p(R.line(400, 100, 400, 420), "k", 3), ...L1.map((s, i) => qt(L(s), 210, 210 + i * 80, 28, "k")), ...L2.map((s, i) => qt(L(s), 590, 210 + i * 80, 28, "o")), A.hl(450, 176, 280, 50)];
    }, say: t3("En nyhetsartikel berättar fakta och är neutral. En krönika är personlig: skribenten skriver jag, tycker till och använder humor, ironi och överdrift. Det kallas skribentens röst. På slutet kommer ofta en allvarlig poäng.", "A news article tells facts and is neutral. A column is personal: the writer says I, gives an opinion and uses humour, irony and exaggeration. That is called the writer's voice. At the end there is often a serious point.", "الخبر الصحفي ينقل الحقائق ويكون محايدًا. أمّا مقالة الرأي فهي شخصية: يكتب الكاتب «أنا» ويعبّر عن رأيه ويستخدم الدعابة والسخرية والمبالغة. هذا ما يُسمّى صوت الكاتب. وفي النهاية تأتي غالبًا فكرة جادّة.")}],
  read: [
    {q: "Vad handlar Saras krönika om?", o: ["Skärmtid och hennes mobil", "En fotbollsmatch i regnet", "Skolans nya matsal"], why: "Del 1: Den handlar om skärmtid."},
    {q: "Hur länge hade Sara tittat på skärmen i söndags, enligt mobilen?", o: ["I nio timmar", "I sju timmar och tolv minuter", "I fyrtio minuter"], why: "Del 2: Enligt mobilen hade jag tittat på skärmen i nio timmar."},
    {q: "Vad tittade Sara på när hon bara skulle kolla en sak?", o: ["Videor om katter som är rädda för gurkor", "Recept på tårtor", "En film på japanska"], why: "Del 2: fyrtio videor om katter som är rädda för gurkor."},
    {q: "Vilken regel har Saras familj?", o: ["Inga mobiler vid middagen", "Ingen tv efter klockan nio", "Mobilen ska vara avstängd i skolan"], why: "Del 4: inga mobiler vid middagen."},
    {q: "Vad är ironi, enligt Lena?", o: ["Att säga motsatsen till det man menar", "Att skriva en rolig rubrik", "Att berätta fakta utan åsikter"], why: "Del 4: ”Man säger motsatsen till det man menar.”"},
    {q: "Vilken kompromiss vill Sara göra med mobilen?", o: ["Den ska ibland ligga i ett annat rum.", "Hon ska kasta den i sjön.", "Hon ska bara använda den på söndagar."], why: "Del 5: ibland får den ligga i ett annat rum."},
    {q: "Varför skriver Sara att hennes tummar har sprungit ett maraton?", o: ["För att visa med en överdrift hur mycket hon scrollar", "För att hon har tränat inför ett lopp", "För att hennes tummar gör ont"], why: "Det är inte sant på riktigt. Hon överdriver för att visa hur mycket hon scrollar."},
    {q: "Varför frågar Yasmin om Amir är sjuk?", o: ["Hon är inte van att se honom utan mobilen.", "Han hostar hela kvällen.", "Han ligger i sängen mitt på dagen."], why: "Amir har just stängt av mobilen, och det gör han nästan aldrig."},
    {q: "Vad visar det att Yasmin tar fram sin surfplatta i slutet?", o: ["Att det är svårt att bryta en vana", "Att hon vill hjälpa Amir att tänka", "Att hon ska göra sina läxor"], why: "Hon funderar en sekund och tar sedan fram skärmen ändå. Vanan är starkare."}],
  gram(lv, write): Problem {
    const hint = {say: IRH, draw: [] as Draw[]};
    if (write || lv === 2) {
      const it = pick(IRQ.filter(x => x[2] === "o"));
      return {kind: "text", ans: it[5], show: it[5][0], q: [...irQ(it, t3("Skriv orden som överdriver.", "Write the words that exaggerate.", "اكتب الكلمات التي فيها مبالغة.")), qt(L(t3(`Personen menar: ${it[3]}`, `The person means: ${it[3]}`, `يقصد الشخص: ${it[3]}`)), 400, 400, 24, "k")], sol: [A.tx(it[5][0], 400, 440, 40, "g")], hint};
    }
    const it = pick(lv === 0 ? IRQ : IRQ.filter(x => x[2] !== "r"));
    if (lv === 1 && Math.random() < .5) {
      const opts = shuffle([it[3], ...it[4]]);
      return {kind: "choice", opts, ans: opts.indexOf(it[3]), show: it[3], q: irQ(it, t3("Vad menar personen egentligen?", "What does the person really mean?", "ماذا يقصد الشخص حقًّا؟")), sol: [A.tx(it[3], 400, 420, 34, "g")], hint};
    }
    const opts = ["i", "o", "r"].map(k => L(IRK[k])), right = L(IRK[it[2]]);
    return {kind: "choice", opts, ans: opts.indexOf(right), show: right, q: irQ(it, t3("Är det ironi, överdrift eller rakt på sak?", "Is it irony, exaggeration or meant literally?", "هل هي سخرية أم مبالغة أم كلام مباشر؟")), sol: [A.tx(right, 400, 420, 40, "g")], hint};
  },
  help: [{say: IRH, draw: () => [A.tx(L(t3("ironi = säga motsatsen", "irony = say the opposite", "السخرية = قول العكس")), 400, 160, 38, "o"), A.tx(L(t3("överdrift = göra det större", "exaggeration = make it bigger", "المبالغة = تكبير الأمر")), 400, 260, 38, "r"), A.tx(L(t3("rakt på sak = mena det man säger", "literal = mean what you say", "المباشر = تقصد ما تقول")), 400, 360, 34, "g")]}]});

/* ================= unit 8: Dikten vid havet (liknelse, metafor, personifikation) ================= */
word("dikt", {sv: "dikt (en)", m: "dikt(en|er|erna)?", d: t3("En kort text med rader och ofta rytm, som säger mycket med få ord.", "A short text in lines, often with rhythm, that says a lot with few words.", "نصّ قصير مكتوب في أسطر، وغالبًا له إيقاع، يقول الكثير بكلمات قليلة."), ex: "Amir skrev en dikt om havet.", tr: {en: "poem", ar: "قصيدة"}, syn: ["poem"], wrong: ["roman", "recept"], gap: ["Lena bad alla skriva en", "dikt", "om havet."], gapForm: "dikt", form: "en dikt – dikter"});
word("strof", {sv: "strof (en)", m: "strof(en|er|erna)?", d: t3("En grupp rader i en dikt, som ett stycke i en vanlig text.", "A group of lines in a poem, like a paragraph in an ordinary text.", "مجموعة أسطر في قصيدة، مثل الفقرة في النص العادي."), ex: "Den första strofen handlar om solen.", tr: {en: "stanza, verse", ar: "مقطع شعريّ"}, syn: ["vers"], wrong: ["rubrik", "kapitel"], gap: ["Hennes första", "strof", "handlade om solen över vattnet."], gapForm: "strof", form: "en strof – strofer"});
word("liknelse", {sv: "liknelse (en)", m: "liknelse(n|r|rna)?", d: t3("En bild som jämför två saker med ordet som.", "An image that compares two things using the word som (like, as).", "صورة تقارن بين شيئين باستخدام كلمة som (مثل)."), ex: "”Solen glittrar som tusen speglar” är en liknelse.", tr: {en: "simile", ar: "تشبيه"}, syn: ["jämförelse"], wrong: ["fråga", "rubrik"], gap: ["”Grå som en gammal filt” är en", "liknelse", "eftersom den har ordet som."], gapForm: "liknelse", form: "en liknelse – liknelser"});
word("metafor", {sv: "metafor (en)", m: "metafor(en|er|erna)?", d: t3("En bild som säger att något är något annat, utan ordet som.", "An image that says something is something else, without the word som.", "صورة تقول إن شيئًا هو شيء آخر، دون كلمة som."), ex: "”Havet är farfars minne” är en metafor.", tr: {en: "metaphor", ar: "استعارة"}, syn: ["språklig bild"], wrong: ["mening", "rim"], gap: ["”Havet är en gammal filt” är en", "metafor", "eftersom ordet som saknas."], gapForm: "metafor", form: "en metafor – metaforer"});
word("horisont", {sv: "horisont (en)", m: "horisont(en|er)?", d: t3("Linjen långt borta där himlen och havet eller marken möts.", "The line far away where the sky meets the sea or the land.", "الخطّ البعيد حيث تلتقي السماء بالبحر أو بالأرض."), ex: "Amir tittade ut mot horisonten.", tr: {en: "horizon", ar: "الأفق"}, syn: ["synrand"], wrong: ["strand", "brygga"], gap: ["Amir stod kvar och tittade ut mot", "horisonten", "där himlen mötte havet."], gapForm: "horisonten", form: "en horisont – horisonter"});
word("brus", {sv: "brus (ett)", m: "brus(et|a|ar|ade)?", d: t3("Ett jämnt, susande ljud, till exempel från havet eller vinden.", "A steady, rushing sound, for example from the sea or the wind.", "صوت متواصل يشبه الهمس، مثل صوت البحر أو الريح."), ex: "Vi hörde havets brus.", tr: {en: "roar, rushing sound", ar: "هدير"}, syn: ["sus"], opp: ["tystnad"], wrong: ["ljus", "skratt"], gap: ["Vågorna slog mot stenarna med ett jämnt", "brus", "som aldrig tog slut."], gapForm: "brus", form: "ett brus · brusa – brusade"});
word("glittra", {sv: "glittra", m: "glittra(r|de|t|nde)?", d: t3("Blänka med många små ljusa punkter.", "Shine with many small points of light.", "أن يلمع بنقاط ضوء صغيرة كثيرة."), ex: "Solen glittrar på vattnet.", tr: {en: "glitter, sparkle", ar: "يتلألأ"}, syn: ["glänsa", "blänka"], wrong: ["viska", "frysa"], gap: ["Solen", "glittrar", "på vattnet som tusen små speglar."], gapForm: "glittrar", form: "glittra – glittrade – har glittrat"});
word("vemod", {sv: "vemod (ett)", m: "vemod(et|ig|igt|iga)?", d: t3("En stilla sorg, ofta blandad med glädje eller längtan.", "A quiet sadness, often mixed with joy or longing.", "حزن هادئ، غالبًا يختلط بالفرح أو بالحنين."), ex: "Amir kände ett vemod när han tänkte på farfar.", tr: {en: "wistfulness, melancholy", ar: "شجن، حزن هادئ"}, syn: ["stilla sorg"], wrong: ["ilska", "hunger"], gap: ["När han tänkte på farfar kände han ett", "vemod", "som han inte kunde förklara."], gapForm: "vemod", form: "ett vemod · vemodig – vemodigt – vemodiga"});
word("svpersonifikation", {sv: "personifikation (besjälning)", m: "personifikation(en|er)?|besjälning(en|ar)?", d: t3("En bild där något som inte är en människa gör som en människa.", "An image where something that is not a person acts like a person.", "صورة يتصرّف فيها شيء ليس إنسانًا كأنه إنسان."), ex: "Vågorna viskar mot stenarna.", tr: {en: "personification", ar: "تشخيص، أنسنة"}});

