/* [line, kind l(iknelse)/m(etafor)/p(ersonifikation)] */
const BIQ: [string, "l" | "m" | "p"][] = [
  ["Solen glittrar som tusen speglar.", "l"], ["Måsarna skriker som barn på rast.", "l"], ["Havet är grått som en gammal filt.", "l"], ["Hans block var lika tomt som himlen.", "l"], ["Månen hänger som en lampa över sjön.", "l"], ["Molnen är mjuka som bomull.", "l"], ["Hon springer snabbt som vinden.", "l"],
  ["Havet är farfars minne.", "m"], ["Horisonten är en tunn tråd.", "m"], ["Livet är en lång resa.", "m"], ["Skolgården är en djungel på rasten.", "m"], ["Mitt hjärta är en sten i dag.", "m"], ["Stjärnorna är himlens lampor.", "m"], ["Vågorna är vita hästar.", "m"],
  ["Vågorna viskar mot stenarna.", "p"], ["Vinden river i min jacka.", "p"], ["Solen tittar fram mellan molnen.", "p"], ["Havet suckar i mörkret.", "p"], ["Regnet knackar otåligt på fönstret.", "p"], ["Träden dansar i stormen.", "p"], ["Månen sover bakom molnen.", "p"]];
const BIK: Record<string, string> = {l: "liknelse", m: "metafor", p: "personifikation"};
const BIH = t3("Liknelse: två saker jämförs med som. Metafor: något är något annat, utan som. Personifikation: något som inte är en människa gör som en människa.", "Simile: two things are compared with som. Metaphor: something is something else, without som. Personification: something that is not a person acts like a person.", "التشبيه: نقارن بين شيئين باستخدام som. الاستعارة: الشيء هو شيء آخر، بلا som. التشخيص: شيء ليس إنسانًا يتصرّف كإنسان.");

defineUnit({id: "sv8h", year: 8, ord: 8, title: t3("Dikten vid havet", "The poem by the sea", "القصيدة عند البحر"), storyTitle: "Dikten vid havet",
  icon: ICON(`<rect width="320" height="90" fill="#f2b38a"/><rect y="90" width="320" height="90" fill="#3f5f80"/><path d="M0 90H320" stroke="#1d2433" stroke-width="2"/><circle cx="240" cy="70" r="26" fill="#fff6c4"/>${[[200, 120], [240, 112], [280, 126], [220, 140]].map(([x, y]) => sparkle(x, y, 7)).join("")}<rect x="40" y="40" width="96" height="110" fill="#fff" stroke="#9aa8c4" stroke-width="3"/>${[0, 1, 2, 3, 4].map(i => `<path d="M52 ${66 + i * 16}h${i % 2 ? 50 : 72}" stroke="#2257c9" stroke-width="4" stroke-linecap="round"/>`).join("")}`, "#f2b38a"),
  words: ["dikt", "strof", "liknelse", "metafor", "horisont", "brus", "glittra", "vemod"], terms: ["svpersonifikation"],
  story: [
    {text: ["I slutet av oktober tog Lena med 8B till stranden nedanför Hagaby. ”I dag ska ni skriva en dikt”, sa hon. ”Ingen skärmtid, inga mobiler. Bara ni, havet och ett block.”", "Det blåste kallt. Vågorna slog mot stenarna, och det hördes ett jämnt brus. Sara satte sig på en sten och började skriva direkt. Amir stod kvar och tittade ut mot horisonten."],
      pic: P8[0], say: t3("8B är vid havet. Vad ska de göra där?", "8B is by the sea. What are they going to do there?", "صف 8B عند البحر. ماذا سيفعلون هناك؟")},
    {text: ["Lena samlade klassen runt sig. ”En dikt säger mycket med få ord”, sa hon. ”Därför använder poeter bilder. En liknelse jämför två saker med ordet som: Havet är grått som en gammal filt.”", "”En metafor jämför utan som”, fortsatte hon. ”Havet är en gammal filt. Man kan också låta saker göra som människor. Vågorna viskar. Vinden river i jackan.”"],
      pic: P8[1], say: t3("Lena förklarar tre sorters bilder. Vad är skillnaden mellan en liknelse och en metafor?", "Lena explains three kinds of images. What is the difference between a simile and a metaphor?", "تشرح لينا ثلاثة أنواع من الصور. ما الفرق بين التشبيه والاستعارة؟")},
    {text: ["Sara skrev snabbt. Hennes första strof handlade om solen, som just hade tittat fram mellan molnen: Solen glittrar på vattnet / som tusen små speglar. / Måsarna skriker / som barn på en rast.", "”Två liknelser!” sa hon stolt och visade Amir. ”Snyggt”, sa han. Själv hade han inte skrivit ett enda ord. Hans block var lika tomt som himlen."],
      pic: P8[2], say: t3("Läs Saras strof. Hitta orden som visar att det är liknelser.", "Read Sara's stanza. Find the words that show they are similes.", "اقرأ مقطع سارة. ابحث عن الكلمات التي تبيّن أنها تشبيهات.")},
    {text: ["Amir satte sig längst ut på bryggan. Han tänkte på farfar, som brukade berätta om ett annat hav, långt borta, där han hade simmat som pojke. Farfar blev alltid tyst efteråt.", "Amir kände ett vemod som han inte kunde förklara. Det var inte sorg, och det var inte glädje. Det var något mittemellan, som när sommarlovet tar slut. Han hade börjat reflektera mer sedan han lade bort mobilen på kvällarna."],
      pic: P8[3], say: t3("Amir tänker på farfar. Vad är vemod för en känsla?", "Amir thinks about his grandfather. What kind of feeling is wistfulness?", "يفكّر أمير في جدّه. ما نوع شعور الشجن؟")},
    {text: ["Långsamt började han skriva. Han strök över och skrev igen. När skymningen kom, hade han en strof: Havet är farfars minne, / det rullar fram och tillbaka. / Horisonten är en tunn tråd / mellan här och där.", "Han läste den tyst för sig själv och rös. Det var första gången som han hade skrivit något som kändes sant."],
      pic: P8[4], say: t3("Amir skriver en strof med metaforer. Vad betyder det att havet är farfars minne?", "Amir writes a stanza with metaphors. What does it mean that the sea is his grandfather's memory?", "يكتب أمير مقطعًا فيه استعارات. ماذا يعني أن البحر هو ذاكرة الجدّ؟")},
    {text: ["Nästa dag läste några elever sina dikter högt. Noah hade skrivit om en mås som stal hans macka, och alla skrattade. Sedan var det Amirs tur. Han ville egentligen inte, men Lena nickade uppmuntrande.", "När han läste den sista raden, blev det helt tyst i klassrummet. Det var en tystnad som inte var pinsam. Ingen scrollade i något flöde, och ingen viskade."],
      pic: P8[5], say: t3("Amir läser sin dikt högt. Hur reagerar klassen?", "Amir reads his poem aloud. How does the class react?", "يقرأ أمير قصيدته بصوت عالٍ. كيف يتفاعل الصف؟")},
    {text: ["”Havet är farfars minne. Det är en metafor”, sa Lena efter en stund. ”Den säger mer än en lång krönika. Vad tänkte du på?” ”På farfar”, sa Amir. ”Jag tror att han längtar hem ibland.”", "På vägen hem frågade Sara om hon fick läsa dikten igen. ”Du borde visa den för din farfar”, sa hon. Amir svarade inte. Men på kvällen skrev han av dikten med sin finaste handstil och lade den i ett kuvert."],
      pic: P8[6], say: t3("Amir lägger dikten i ett kuvert. Vem tror du att den är till?", "Amir puts the poem in an envelope. Who do you think it is for?", "يضع أمير القصيدة في ظرف. لمن تظنّ أنها؟")}],
  wordsSay: t3("Nya ord från stranden! Tryck på ett ord för att se vad det betyder.", "New words from the beach! Tap a word to see what it means.", "كلمات جديدة من الشاطئ! اضغط على كلمة لترى معناها."),
  grammar: [
    {draw: () => [A.wipe(), head(t3("Liknelse: jämför med som", "Simile: compare with som", "التشبيه: المقارنة بـ som")),
      ...boxes([["Havet är grått", "b"], ["som", "o", L(t3("jämför", "compares", "يقارن"))], ["en gammal filt.", "g"]], 170, 40),
      ...boxes([["Solen glittrar", "b"], ["som", "o"], ["tusen speglar.", "g"]], 320, 40),
      qt(L(t3("två saker + som = liknelse", "two things + som = simile", "شيئان + som = تشبيه")), 400, 450, 28, "o")],
    say: t3("I en liknelse jämför man två saker med ordet som. Havet är grått som en gammal filt. Solen glittrar som tusen speglar. Ordet som visar att det är en jämförelse.", "In a simile you compare two things with the word som. The sea is grey like an old blanket. The sun sparkles like a thousand mirrors. The word som shows that it is a comparison.", "في التشبيه نقارن بين شيئين بكلمة som. البحر رماديّ مثل بطانية قديمة. الشمس تتلألأ مثل ألف مرآة. كلمة som تبيّن أنها مقارنة.")},
    {draw: () => [A.wipe(), head(t3("Metafor: utan som", "Metaphor: without som", "الاستعارة: بلا som")),
      ...boxes([["Havet", "b"], ["är", "r", L(t3("är – inte som", "is – not like", "هو – وليس مثل"))], ["farfars minne.", "g"]], 170, 42),
      ...boxes([["Havet är", null], ["som", "o", L(t3("liknelse", "simile", "تشبيه"))], ["en filt.", null]], 300, 36),
      ...boxes([["Havet är", null], ["en filt.", "r", L(t3("metafor", "metaphor", "استعارة"))]], 410, 36)],
    say: t3("En metafor säger att något är något annat, utan ordet som. Havet är farfars minne. Bilden blir starkare, och läsaren får själv tänka ut vad den betyder.", "A metaphor says that something is something else, without the word som. The sea is grandfather's memory. The image becomes stronger, and the reader has to work out what it means.", "الاستعارة تقول إن شيئًا هو شيء آخر، بلا كلمة som. البحر هو ذاكرة الجدّ. تصبح الصورة أقوى، وعلى القارئ أن يفهم معناها بنفسه.")},
    {draw: () => [A.wipe(), head(t3("Personifikation", "Personification", "التشخيص")),
      ...boxes([["Vågorna", "b", L(t3("inte en människa", "not a person", "ليست إنسانًا"))], ["viskar", "g", L(t3("gör som en människa", "acts like a person", "تتصرّف كإنسان"))], ["mot stenarna.", null]], 170, 42),
      ...boxes([["Vinden", null], ["river", "g"], ["i jackan.", null]], 300, 36), ...boxes([["Solen", null], ["tittar", "g"], ["fram.", null]], 380, 36),
      qt("The waves whisper.", 250, 455, 26, "k"), qt("الأمواج تهمس", 580, 455, 30, "o")],
    say: t3("Vågor kan inte viska på riktigt, och solen har inga ögon. När något som inte är en människa gör som en människa, kallas det personifikation eller besjälning. Samma bild finns på engelska och arabiska.", "Waves can't really whisper, and the sun has no eyes. When something that is not a person acts like a person, it is called personification. The same image exists in English and Arabic.", "الأمواج لا تهمس حقًّا، والشمس ليس لها عيون. عندما يتصرّف شيء ليس إنسانًا كأنه إنسان، يُسمّى ذلك تشخيصًا أو أنسنة. والصورة نفسها موجودة في الإنجليزية والعربية.")}],
  read: [
    {q: "Var skrev 8B sina dikter?", o: ["På stranden nedanför Hagaby", "I skolbiblioteket", "I en skog bakom skolan"], why: "Del 1: Lena tog med 8B till stranden nedanför Hagaby."},
    {q: "Vad är skillnaden mellan en liknelse och en metafor, enligt Lena?", o: ["En liknelse har ordet som, men det har inte en metafor.", "En metafor måste alltid rimma.", "En liknelse handlar alltid om havet."], why: "Del 2: ”En metafor jämför utan som.”"},
    {q: "Vad jämförde Sara solens glitter med?", o: ["Tusen små speglar", "En gammal filt", "Barn på en rast"], why: "Del 3: Solen glittrar på vattnet / som tusen små speglar."},
    {q: "Vem tänkte Amir på när han satt på bryggan?", o: ["Sin farfar", "Sin lillasyster Yasmin", "Lena"], why: "Del 4: Han tänkte på farfar."},
    {q: "Hur beskrivs vemodet i texten?", o: ["Som något mittemellan sorg och glädje", "Som en stark ilska", "Som en stor rädsla"], why: "Del 4: Det var inte sorg, och det var inte glädje."},
    {q: "Vad hade Noah skrivit om?", o: ["En mås som stal hans macka", "Havet i storm", "Sin farfars båt"], why: "Del 6: en mås som stal hans macka."},
    {q: "Varför blev farfar tyst när han hade berättat om havet?", o: ["Han saknade platsen där han växte upp.", "Han var trött i halsen.", "Han hade glömt resten av historien."], why: "Havet fanns långt borta, i landet där han var pojke. Amir tror att han längtar hem."},
    {q: "Varför var tystnaden efter Amirs dikt inte pinsam?", o: ["Klassen blev berörd av dikten.", "Ingen hade lyssnat.", "Alla väntade på rasten."], why: "Ingen scrollade eller viskade. Alla lyssnade och tänkte på det han hade läst."},
    {q: "Vad tror du att Amir ska göra med kuvertet?", o: ["Ge dikten till farfar", "Lämna in den som läxa", "Gömma den för Sara"], why: "Sara sa att han borde visa dikten för farfar, och Amir skrev av den med sin finaste handstil."}],
  gram(lv, write): Problem {
    const hint = {say: BIH, draw: [] as Draw[]}, [line, k] = pick(BIQ), kinds = ["liknelse", "metafor", "personifikation"];
    if (write || lv === 2) return {kind: "text", ans: k === "p" ? [BIK[k], "besjälning"] : [BIK[k]], show: BIK[k], q: [A.wipe(), head(t3("Vilken bild? Skriv liknelse, metafor eller personifikation.", "Which image? Write liknelse, metafor or personifikation.", "ما نوع الصورة؟ اكتب liknelse أو metafor أو personifikation."), 70, 26), ...svLines(line, 230, 42, "b")], sol: [A.tx(BIK[k], 400, 420, 40, "g")], hint};
    if (lv === 1 && Math.random() < .5) {
      const want = pick(["l", "m", "p"]), opts = shuffle(["l", "m", "p"].map(c => pick(BIQ.filter(x => x[1] === c))[0])), right = opts.find(o => BIQ.some(x => x[0] === o && x[1] === want)) as string;
      return {kind: "choice", opts, ans: opts.indexOf(right), show: right, q: [A.wipe(), head(t3(`Vilken mening är en ${BIK[want]}?`, `Which sentence is a ${BIK[want]}?`, `أي جملة هي ${BIK[want]}؟`), 90, 36)], sol: [A.tx(right, 400, 400, 36, "g")], hint};
    }
    return {kind: "choice", opts: kinds, ans: kinds.indexOf(BIK[k]), show: BIK[k], q: [A.wipe(), head(t3("Liknelse, metafor eller personifikation?", "Simile, metaphor or personification?", "تشبيه أم استعارة أم تشخيص؟"), 70, 32), ...svLines(line, 230, 42, "b")], sol: [A.tx(BIK[k], 400, 420, 40, "g")], hint};
  },
  help: [{say: BIH, draw: () => [A.tx("grå som en filt → liknelse", 400, 160, 38, "o"), A.tx("havet är ett minne → metafor", 400, 260, 38, "r"), A.tx("vågorna viskar → personifikation", 400, 360, 36, "g")]}]});

