word("lanord", {sv: "lånord (ett)", m: "lånord(et|en)?", d: t3("Ett ord som ett språk har lånat från ett annat språk.", "A word that one language has borrowed from another language.", "كلمة استعارتها لغة من لغة أخرى."), ex: "Kaffe är ett lånord.", tr: {en: "loanword", ar: "كلمة دخيلة"}, syn: ["inlånat ord"], wrong: ["rim", "namn"], gap: ["Kaffe är ett", "lånord", "som har kommit till svenskan från arabiskan."], gapForm: "lånord", form: "ett lånord – lånord"});
word("ursprung", {sv: "ursprung (ett)", m: "ursprung(et|en|lig|ligen|liga|ligt)?", d: t3("Var något kommer ifrån från början.", "Where something comes from at the start.", "المكان الذي جاء منه الشيء في البداية."), ex: "Ordet har sitt ursprung i arabiskan.", tr: {en: "origin", ar: "أصل"}, syn: ["härkomst"], wrong: ["slut", "mål"], gap: ["Ta reda på vilket", "ursprung", "ordet har."], gapForm: "ursprung", form: "ett ursprung · ursprunglig"});
word("sprakhistoria", {sv: "språkhistoria (en)", m: "språkhistori(a|en|sk|ska|skt)", d: t3("Kunskapen om hur ett språk har förändrats genom tiden.", "Knowledge about how a language has changed over time.", "معرفة كيف تغيّرت لغة عبر الزمن."), ex: "I november läste 8B om språkhistoria.", tr: {en: "history of language", ar: "تاريخ اللغة"}, syn: ["språkets historia"], wrong: ["matematik", "geografi"], gap: ["Lena berättade om svensk", "språkhistoria", "från medeltiden till i dag."], gapForm: "språkhistoria", form: "en språkhistoria"});
word("latin", {sv: "latin (ett)", m: "latin(et|ets|sk|ska|skt)?", d: t3("Det gamla språket i Rom. Kyrkan och forskarna skrev på latin i många hundra år.", "The old language of Rome. The church and scholars wrote in Latin for many hundreds of years.", "لغة روما القديمة. كتبت الكنيسة والعلماء باللاتينية مئات السنين."), ex: "Skriva kommer från latinets scribere.", tr: {en: "Latin", ar: "اللاتينية"}, syn: ["romarnas språk"], wrong: ["danska", "engelska"], gap: ["Kyrkans språk på medeltiden var", "latin", "och därför lånade vi många ord därifrån."], gapForm: "latin", form: "latin · latinsk – latinska"});
word("influens", {sv: "påverkan (en)", m: "påverkan", d: t3("När något eller någon förändrar något annat.", "When something or someone changes something else.", "عندما يغيّر شيء أو شخص شيئًا آخر."), ex: "Franskan hade stor påverkan på svenskan.", tr: {en: "influence", ar: "تأثير"}, syn: ["inflytande"], wrong: ["tystnad", "glömska"], gap: ["Engelskan har stor", "påverkan", "på svenskan i dag."], gapForm: "påverkan", form: "en påverkan · påverka – påverkade"});
word("forsvenska", {sv: "försvenska", m: "försvenska(r|de|t|d|s|des|ts)?", d: t3("Ändra ett ord från ett annat språk så att det ser ut och låter svenskt.", "Change a word from another language so that it looks and sounds Swedish.", "أن تغيّر كلمة من لغة أخرى حتى تبدو وتُنطق كأنها سويدية."), ex: "Trottoir har vi försvenskat till trottoar.", tr: {en: "make Swedish, adapt to Swedish", ar: "يُكيّف الكلمة لتصبح سويدية"}, syn: ["göra svensk"], wrong: ["glömma", "stava fel"], gap: ["Vi har", "försvenskat", "mail till mejl."], gapForm: "försvenskat", form: "försvenska – försvenskade – har försvenskat"});
word("nybildning", {sv: "nybildning (en)", m: "nybildning(en|ar|arna)?", d: t3("Ett helt nytt ord som någon har skapat.", "A completely new word that someone has created.", "كلمة جديدة تمامًا ابتكرها أحد."), ex: "Dator är en nybildning från 1960-talet.", tr: {en: "new coinage, new word", ar: "كلمة مستحدثة"}, syn: ["nyord"], wrong: ["citat", "dialekt"], gap: ["Dator är en", "nybildning", "från 1960-talet."], gapForm: "nybildning", form: "en nybildning – nybildningar"});
