const suitcase = (x: number, y: number, s = 1) => `<g transform="translate(${x} ${y}) scale(${s})"><rect x="-60" y="-40" width="120" height="80" rx="10" fill="#a0522d"/><rect x="-18" y="-54" width="36" height="16" rx="6" fill="none" stroke="#5b2d10" stroke-width="6"/><path d="M-60 -6H60" stroke="#5b2d10" stroke-width="3"/>${["kaffe", "soffa", "mejl", "byrå"].map((w, i) => `<rect x="${-54 + (i % 2) * 56}" y="${-34 + Math.floor(i / 2) * 36}" width="50" height="22" rx="4" fill="#fff6c4"/><text x="${-29 + (i % 2) * 56}" y="${-18 + Math.floor(i / 2) * 36}" font-family="Caveat,cursive" font-weight="700" font-size="16" text-anchor="middle" fill="#1d2433">${w}</text>`).join("")}</g>`;
