const CQ: [string, string, string, string, string, string][] = [
  ["Om vi", "åkte", "till Stockholm, skulle det kosta 1 800 kronor.", "åker", "åkt", "åka"],
  ["Om vi", "hade", "mer pengar, skulle vi åka längre bort.", "har", "haft", "ha"],
  ["Om Ibrahim", "frågade", "affärerna, skulle någon kanske bli sponsor.", "frågar", "frågat", "fråga"],
  ["Om alla", "sålde", "tio kakor, skulle vi få in 5 000 kronor.", "säljer", "sålt", "sälja"],
  ["Om vi", "valde", "Stockholm, skulle några inte ha råd.", "väljer", "valt", "välja"],
  ["Om det", "regnade", "vid Hagasjön, skulle vi sova i tält ändå.", "regnar", "regnat", "regna"],
  ["Om Noah", "kunde", "välja, skulle han åka till Stockholm.", "kan", "kunnat", "kunna"],
  ["Om jag", "var", "du, skulle jag rösta för kompromissen.", "är", "varit", "vara"],
  ["Om vi vann på lotteriet,", "skulle", "vi åka till Japan.", "ska", "kommer", "ska"],
  ["Om jag var rektor,", "skulle", "jag betala hela resan.", "ska", "kommer", "ska"],
  ["Om vi inte fick ihop pengarna,", "skulle", "vi stanna hemma.", "ska", "kommer", "ska"],
  ["Om Elsa inte räknade så noga,", "skulle", "vi få ett underskott.", "ska", "kommer", "ska"]];
const CQH = t3("Om + verbet i preteritum (åkte, hade, var). Sedan skulle + infinitiv (skulle åka). Det visar att något är tänkt och inte sant just nu.", "Om + the verb in the past tense (åkte, hade, var). Then skulle + infinitive (skulle åka). It shows that something is imagined and not true right now.", "om + الفعل في الماضي (åkte وhade وvar). ثم skulle + المصدر (skulle åka). هذا يبيّن أن الأمر متخيَّل وليس صحيحًا الآن.");

defineUnit({id: "sv8j", year: 8, ord: 10, title: t3("Klassresan och budgeten", "The class trip and the budget", "رحلة الصف والميزانيّة"), storyTitle: "Klassresan och budgeten",
  icon: ICON(`${jar(80, 140, 8)}${train(150, 70)}${tent(250, 160)}${label(210, 50, "om … skulle …", 28, "#2257c9")}`, "#e8f4fb"),
  words: ["budget8", "insamling", "sponsor", "overskott", "underskott", "rösta8", "majoritet", "prioritera"], terms: ["svvillkor"],
  story: [
    {text: ["I januari kom den stora frågan: vart skulle 8B åka på klassresa i maj? Lena skrev två förslag på tavlan: A, två dagar i Stockholm. B, paddling och en natt i tält vid Hagasjön. Klassen skulle rösta, och majoriteten skulle bestämma.", "”Men först måste vi titta på vår budget”, sa Lena. ”Skolan betalar 200 kronor per elev. Resten måste ni ordna själva.” Sara ville genast till Stockholm. Amir sa ingenting. Han räknade."],
      pic: P10[0], say: t3("8B ska välja klassresa. Vilka är de två förslagen?", "8B is choosing a class trip. What are the two suggestions?", "سيختار صف 8B رحلة. ما الاقتراحان؟")},
    {text: ["Elsa, som var klassens kassör, räknade på tavlan. ”Om vi åkte till Stockholm, skulle det kosta ungefär 1 800 kronor per person”, sa hon. ”Tåget är dyrast. Om vi paddlade vid Hagasjön, skulle det kosta 300.”", "Hon drog bort skolans pengar. ”Då skulle vi ha ett underskott på 40 000 kronor för Stockholm.” Noah stönade. ”Det är ju inte rimligt!”"],
      pic: P10[1], say: t3("Elsa räknar. Hur stort blir underskottet för Stockholm?", "Elsa does the maths. How big is the deficit for Stockholm?", "إلسا تحسب. كم سيكون العجز لرحلة ستوكهولم؟")},
    {text: ["”Vi kan ordna en insamling”, föreslog Sara. ”Vi säljer kakor på föräldramötet och har lotteri på vårmarknaden.” ”Och om vi frågade affärerna i Hagaby?” sa Ibrahim. ”Någon kanske skulle vilja bli sponsor.”", "Amir räknade tyst. Även om allt gick perfekt, skulle de inte få ihop mer än 15 000 kronor. ”Det är som att fylla havet med en tesked”, mumlade han. ”Snygg liknelse”, viskade Sara. ”Men du har fel.”"],
      pic: P10[2], say: t3("Klassen har idéer om pengar. Vad menar Amir med en tesked?", "The class has ideas about money. What does Amir mean by a teaspoon?", "لدى الصف أفكار لجمع المال. ماذا يقصد أمير بالملعقة الصغيرة؟")},
    {text: ["Lena delade klassen i två lag för en kort debatt. Sara talade för Stockholm. ”Om vi åkte till Stockholm, skulle vi se Vasaskeppet på riktigt. Sådant minns man hela livet.”", "Amir talade för Hagasjön. ”Om vi valde Stockholm, skulle vi behöva sälja kakor varje helg i fyra månader”, sa han. ”Och om vi inte fick ihop pengarna, skulle några inte ha råd att följa med. Ska vi verkligen prioritera en dyr resa framför att alla kan åka?”"],
      pic: P10[3], say: t3("Sara och Amir debatterar. Lägg märke till om och skulle i deras argument.", "Sara and Amir debate. Notice om and skulle in their arguments.", "سارة وأمير يتناظران. لاحظ om وskulle في حججهما.")},
    {text: ["Några började protestera. ”Du överdriver”, sa Noah. ”Vi kan väl jobba lite!” Då räckte Ibrahim upp handen. ”Min familj har inte 1 800 kronor över”, sa han lugnt. Det blev tyst i klassrummet.", "Fler nickade. Lena bad alla reflektera en stund. Sedan sa hon att Sara och Amir skulle förhandla fram en kompromiss innan klassen röstade."],
      pic: P10[4], say: t3("Ibrahim säger något modigt. Hur reagerar klassen?", "Ibrahim says something brave. How does the class react?", "يقول إبراهيم شيئًا شجاعًا. كيف يتفاعل الصف؟")},
    {text: ["Efter lunchen hade de ett nytt förslag: en dag på Universeum i Göteborg, med vanligt tåg, och en natt i tält vid Hagasjön. ”Det skulle kosta 700 kronor per person”, sa Amir. ”Om insamlingen gick bra, skulle det räcka för alla.”", "Klassen röstade. Kompromissen fick 21 röster av 25. Det var en klar majoritet. Sara och Amir gjorde high five."],
      pic: P10[5], say: t3("De hittar en kompromiss. Hur många röstar för den?", "They find a compromise. How many vote for it?", "يجدان حلًّا وسطًا. كم صوتًا حصل عليه؟")},
    {text: ["I april räknade Elsa pengarna. Kakorna och lotteriet hade gett 14 000 kronor, och mataffären vid torget hade blivit sponsor med 2 000. Resan skulle kosta 12 500 kronor mer än skolans pengar.", "”Vi har ett överskott på 3 500 kronor!” sa Elsa. ”Vilken rik klass vi är!” sa Sara och höll upp burken. ”Ironi?” frågade Amir. ”Lite”, sa Sara. ”Men jag är stolt på riktigt.”"],
      pic: P10[6], say: t3("Insamlingen gick bra. Hur stort blev överskottet?", "The fundraising went well. How big was the surplus?", "نجح جمع التبرّعات. كم كان الفائض؟")}],
  wordsSay: t3("Nya ord om pengar och beslut! Tryck på ett ord för att se vad det betyder.", "New words about money and decisions! Tap a word to see what it means.", "كلمات جديدة عن المال والقرارات! اضغط على كلمة لترى معناها."),
  grammar: [
    {draw: () => [A.wipe(), head(t3("Om … skulle …", "If … would …", "لو … لـ …")),
      ...boxes([["Om vi", "b"], ["åkte", "r", L(t3("preteritum", "past tense", "الماضي"))], ["till Stockholm,", null]], 170, 40),
      ...boxes([["skulle", "o", "skulle"], ["vi", "b"], ["se", "g", L(t3("infinitiv", "infinitive", "المصدر"))], ["Vasaskeppet.", null]], 320, 40),
      qt(L(t3("om + preteritum → skulle + infinitiv", "om + past tense → skulle + infinitive", "om + الماضي ← skulle + المصدر")), 400, 450, 28, "o")],
    say: t3("När vi tänker oss något som inte är sant just nu, använder vi om och verbet i preteritum: om vi åkte. Sedan kommer skulle och verbet i grundform: skulle vi se. Det heter en villkorsbisats.", "When we imagine something that isn't true right now, we use om and the verb in the past tense: om vi åkte. Then come skulle and the verb in its basic form: skulle vi se. It is called a conditional clause.", "عندما نتخيّل شيئًا ليس صحيحًا الآن نستخدم om والفعل في الماضي: om vi åkte. ثم تأتي skulle والفعل في صيغة المصدر: skulle vi se. وتُسمّى هذه جملة شرطيّة.")},
    {draw: () => [A.wipe(), head(t3("Verklig plan eller tänkt?", "Real plan or imagined?", "خطة حقيقية أم متخيَّلة؟")),
      ...boxes([["Om vi", null], ["säljer", "g", L(t3("presens", "present", "المضارع"))], ["kakor,", null], ["kan", "g"], ["vi åka.", null]], 170, 34),
      qt(L(t3("verklig plan – det kan hända", "a real plan – it can happen", "خطة حقيقية – يمكن أن تحدث")), 400, 230, 24, "g"),
      ...boxes([["Om vi", null], ["hade", "r", L(t3("preteritum", "past tense", "الماضي"))], ["en miljon,", null], ["skulle", "o"], ["vi åka.", null]], 340, 34),
      qt(L(t3("tänkt – det är inte sant nu", "imagined – it isn't true now", "متخيَّل – ليس صحيحًا الآن")), 400, 400, 24, "o")],
    say: t3("Om vi säljer kakor, kan vi åka. Det är en verklig plan, så vi använder presens. Om vi hade en miljon, skulle vi åka. Det är bara tänkt, så vi använder preteritum och skulle.", "If we sell cakes, we can go. That is a real plan, so we use the present tense. If we had a million, we would go. That is only imagined, so we use the past tense and skulle.", "إذا بعنا الكعك يمكننا أن نسافر: هذه خطة حقيقية، لذلك نستخدم المضارع. لو كان لدينا مليون لسافرنا: هذا متخيَّل فقط، لذلك نستخدم الماضي وskulle.")},
    {draw: () => [A.wipe(), head(t3("Tre språk", "Three languages", "ثلاث لغات")),
      A.tx("Om vi åkte, skulle vi se Vasaskeppet.", 400, 160, 34, "b"), A.tx("If we went, we would see the Vasa ship.", 400, 250, 32, "k"), A.tx("لو ذهبنا، لرأينا سفينة فاسا.", 400, 340, 38, "o"),
      qt("om = if   ·   skulle = would", 400, 420, 28, "r"), qt("لو …، لَـ …", 400, 470, 30, "o")],
    say: t3("Engelskan gör likadant: if we went, we would see. På arabiska börjar man med لو och sätter لـ framför verbet i huvudsatsen. Lägg märke till att skulle kommer direkt efter kommat på svenska.", "English does the same: if we went, we would see. In Arabic you start with لو and put لـ in front of the verb in the main clause. Notice that skulle comes right after the comma in Swedish.", "الإنجليزية تفعل الشيء نفسه: if we went, we would see. وفي العربية نبدأ بـ «لو» ونضع اللام قبل الفعل في جواب الشرط. ولاحظ أن skulle تأتي مباشرة بعد الفاصلة في السويدية.")}],
  read: [
    {q: "Vilka två förslag fanns för klassresan först?", o: ["Stockholm eller paddling vid Hagasjön", "Göteborg eller Malmö", "Fjällen eller Gotland"], why: "Del 1: A, två dagar i Stockholm. B, paddling och en natt i tält vid Hagasjön."},
    {q: "Hur mycket betalar skolan per elev?", o: ["200 kronor", "300 kronor", "1 800 kronor"], why: "Del 1: Skolan betalar 200 kronor per elev."},
    {q: "Hur stort underskott skulle Stockholmsresan ge?", o: ["40 000 kronor", "15 000 kronor", "3 500 kronor"], why: "Del 2: ett underskott på 40 000 kronor för Stockholm."},
    {q: "Vad föreslog Ibrahim?", o: ["Att fråga affärerna om någon ville bli sponsor", "Att ha lotteri på vårmarknaden", "Att stanna hemma i stället"], why: "Del 3: ”Och om vi frågade affärerna i Hagaby?”"},
    {q: "Vilket var Amirs viktigaste argument mot Stockholm?", o: ["Alla kanske inte skulle ha råd att följa med.", "Han tycker inte om att åka tåg.", "Han har redan sett Vasaskeppet."], why: "Del 4: ”Om vi inte fick ihop pengarna, skulle några inte ha råd att följa med.”"},
    {q: "Hur många röstade för kompromissen?", o: ["21 av 25", "Hälften av klassen", "Alla utom Noah"], why: "Del 6: Kompromissen fick 21 röster av 25."},
    {q: "Vad menade Amir med att fylla havet med en tesked?", o: ["Insamlingen skulle inte räcka till Stockholm.", "Han ville hellre bada än resa.", "Klassen borde baka fler kakor."], why: "En tesked är för liten för havet, precis som 15 000 kronor är för lite för en resa som kräver 40 000."},
    {q: "Varför blev det tyst när Ibrahim pratade?", o: ["Det var modigt att säga att familjen har ont om pengar.", "Ibrahim pratade på ett annat språk.", "Lena hade sagt åt alla att vara tysta."], why: "Det kan kännas pinsamt att prata om pengar. Klassen förstod att argumentet gällde på riktigt."},
    {q: "Varför kan Saras ”Vilken rik klass vi är!” vara ironi?", o: ["3 500 kronor är inte särskilt mycket för en hel klass.", "Klassen har vunnit en miljon.", "Sara vill inte åka på resan."], why: "Överskottet räcker inte långt. Sara säger att de är rika, men menar det bara lite."}],
  gram(lv, write): Problem {
    const [pre, right, post, w1, w2, cue] = pick(lv === 0 ? CQ.slice(0, 8) : CQ), hint = {say: CQH, draw: [] as Draw[]};
    const q = (s: T3) => [A.wipe(), head(s, 70, 32), ...svLines(tail(pre, "____", post), 210, 40)];
    if (write || lv === 2) return {kind: "text", ans: [right], show: right, q: [...q(t3("Skriv verbet i rätt form.", "Write the verb in the right form.", "اكتب الفعل بالصيغة الصحيحة.")), A.tx(`(${cue})`, 400, 380, 36, "o")], sol: svLines(tail(pre, right, post), 430, 30, "g", 46), hint};
    const opts = shuffle([right, w1, w2]);
    return {kind: "choice", opts, ans: opts.indexOf(right), show: right, q: q(t3("Vilket ord passar?", "Which word fits?", "أي كلمة تناسب؟")), sol: svLines(tail(pre, right, post), 400, 32, "g", 44), hint};
  },
  help: [{say: CQH, draw: () => [A.tx("Om vi åkte, …", 400, 170, 46, "r"), A.tx("… skulle vi se Vasaskeppet.", 400, 280, 42, "o"), A.tx("om + preteritum → skulle + infinitiv", 400, 390, 30, "b")]}]});

